style.css:
/* ===== Soft Pink & White Theme ===== */

html, body {
    background: #fff9fc !important;
    color: #b8860b !important; /* Gold text */
    font-family: "Segoe UI", "Helvetica Neue", sans-serif !important;
}

/* Main containers */
div, section, article, main, nav, aside, header, footer {
    background: #fffdfd !important;
    color: #b8860b !important;
    border-radius: 12px !important;
}

/* Headings */
h1, h2, h3, h4, h5, h6 {
    color: #d4a017 !important;
}

/* Paragraphs and labels */
p, span, label, li {
    color: #b8860b !important;
}

/* Links */
a {
    color: #d4a017 !important;
    text-decoration: none !important;
}

a:hover {
    color: #e6c34d !important;
    text-shadow: 0 0 4px rgba(212, 160, 23, 0.3);
}

/* Buttons */
button,
input[type="button"],
input[type="submit"] {
    background: #ffd6e7 !important;
    color: #b8860b !important;
    border: 1px solid #ffc2db !important;
    border-radius: 10px !important;
    transition: all 0.2s ease;
}

button:hover,
input[type="button"]:hover,
input[type="submit"]:hover {
    background: #ffcce0 !important;
}

/* Input fields */
input,
textarea,
select {
    background: #fff !important;
    color: #b8860b !important;
    border: 1px solid #ffd6e7 !important;
    border-radius: 8px !important;
}

/* Tables */
table, th, td {
    background: #fffdfd !important;
    color: #b8860b !important;
    border-color: #ffd6e7 !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 12px;
}

::-webkit-scrollbar-track {
    background: #fff0f6;
}

::-webkit-scrollbar-thumb {
    background: #ffc2db;
    border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
    background: #ffb3d1;
}

/* Selection highlight */
::selection {
    background: #ffd6e7;
    color: #8b6508;
}
